import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.2cFhd8Ux.js";const u=JSON.parse('{"title":"Glossary","description":"","frontmatter":{"source":"resources/glossary.md"},"headers":[],"relativePath":"resources/glossary.md","filePath":"resources/glossary.md"}'),n={name:"resources/glossary.md"};function s(i,e,l,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><blockquote><p>AI-specific and course terms, with short definitions and the week that teaches each one. Basic software engineering terms (CI, refactoring, test double, race condition) are assumed, not defined. Product limits, prices and model names are in <a href="./../TOOLS.html">Tool Handout</a>, never here.</p></blockquote><p><strong>Jump to:</strong> <a href="#a">A</a> · <a href="#b">B</a> · <a href="#c">C</a> · <a href="#d">D</a> · <a href="#e">E</a> · <a href="#f">F</a> · <a href="#g">G</a> · <a href="#h">H</a> · <a href="#i">I</a> · <a href="#j">J</a> · <a href="#l">L</a> · <a href="#m">M</a> · <a href="#o">O</a> · <a href="#p">P</a> · <a href="#q">Q</a> · <a href="#r">R</a> · <a href="#s">S</a> · <a href="#t">T</a> · <a href="#v">V</a> · <a href="#w">W</a></p><hr><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><h3 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h3><p>An LLM in a loop with tools: it receives a task, decides on a tool call, the harness runs it and returns the result, and the loop continues until the model stops or a limit is hit. A <em>coding agent</em>&#39;s tools read and write files and run commands. You run, read and extend one in week 1 (<code>mini-agent</code>). <em>Week 1.</em></p><h3 id="agent-loop" tabindex="-1">Agent loop <a class="header-anchor" href="#agent-loop" aria-label="Permalink to &quot;Agent loop&quot;">​</a></h3><p>The cycle at the core of every agent: send the conversation and tool schemas to the model → receive either text or a <a href="#tool-call">tool call</a> → run the tool (after <a href="#approval-gate">approval</a>) → append the result → repeat. Termination conditions (no tool call, a step limit, a budget) are part of the design. <em>Week 1.</em></p><h3 id="agentsmd" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agentsmd" aria-label="Permalink to &quot;AGENTS.md&quot;">​</a></h3><p>A Markdown file at the root of a repository giving coding agents standing instructions: commands, architecture, conventions, scope, what never to do. Many harnesses read it automatically. It is <strong>advice, not enforcement</strong>: an agent can ignore it, so permissions and sandboxes do the enforcing. In 441 repositories, agent-first projects without a committed configuration file saw complexity rise 53% against 27% with one (<a href="https://arxiv.org/abs/2608.25241" target="_blank" rel="noreferrer">Denisov-Blanch et al.</a>). Template: <a href="./../templates/AGENTS.html">AGENTS.md template</a>; patterns: <a href="./agent-patterns.html#agentsmd-structure">Agent Patterns: AGENTS.md structure</a>. <em>Week 3.</em></p><h3 id="agentic-engineering" tabindex="-1">Agentic engineering <a class="header-anchor" href="#agentic-engineering" aria-label="Permalink to &quot;Agentic engineering&quot;">​</a></h3><p>Building software with agents while keeping humans responsible for the specification, the verification and the result. Contrast with <a href="#vibe-coding">vibe coding</a>. <em>Week 1.</em></p><h3 id="agentic-workflow" tabindex="-1">Agentic workflow <a class="header-anchor" href="#agentic-workflow" aria-label="Permalink to &quot;Agentic workflow&quot;">​</a></h3><p>An automated job (for example GitHub Agentic Workflows, which compile Markdown into Actions YAML) in which an agent runs without a human at the keyboard. Each run spends from an allowance, so the per-run cap must be set below any free allowance (<a href="./../setup/safety-contract.html#6-spending-caps-at-zero">safety contract rule 6</a>). <em>Week 13.</em></p><h3 id="ai_logmd" tabindex="-1">AI_LOG.md <a class="header-anchor" href="#ai_logmd" aria-label="Permalink to &quot;AI_LOG.md&quot;">​</a></h3><p>The course&#39;s disclosure file, in every repository: each significant AI session with its tool and model, what was delegated, what was verified and how. Template: <a href="./../templates/AI_LOG.html">AI_LOG.md template</a>. <em>Week 1.</em></p><h3 id="ai-reviewer" tabindex="-1">AI reviewer <a class="header-anchor" href="#ai-reviewer" aria-label="Permalink to &quot;AI reviewer&quot;">​</a></h3><p>A bot that comments on pull requests (CodeRabbit, PR-Agent, Copilot code review). Measure it like any classifier: <a href="#precision-and-recall">precision</a> against a defect key, and how often its comments lead to changes (38.7% of AI comments vs 44.45% of human comments at Atlassian: <a href="https://arxiv.org/abs/2601.01129v2" target="_blank" rel="noreferrer">Tantithamthavorn et al.</a>). <em>Week 9.</em></p><h3 id="approval-gate" tabindex="-1">Approval gate <a class="header-anchor" href="#approval-gate" aria-label="Permalink to &quot;Approval gate&quot;">​</a></h3><p>The point in a harness where a human must confirm a tool call before it runs. <code>mini-agent</code> requires a <code>y</code> for every command and write unless the exact command is on an allowlist. An <strong>approval policy</strong> decides what needs approval. <em>Week 1.</em></p><h3 id="approval-test" tabindex="-1">Approval test <a class="header-anchor" href="#approval-test" aria-label="Permalink to &quot;Approval test&quot;">​</a></h3><p>A <a href="#characterization-test">characterization test</a> that runs many inputs through the code, records every output and side effect in one file, and fails when a later run differs from that approved file; also called a <em>golden master</em>. Scrub what changes on every run (random IDs, the clock), and read the file before you approve it: approving is a claim. <em>Week 8.</em></p><h3 id="assisted-by-trailer" tabindex="-1">Assisted-by trailer <a class="header-anchor" href="#assisted-by-trailer" aria-label="Permalink to &quot;Assisted-by trailer&quot;">​</a></h3><p>The last line of an AI-assisted commit message: <code>Assisted-by: [tool and model]</code>. The convention is LLVM&#39;s. Detection of agent-written commits is unreliable, so recorded attribution is the evidence (<a href="https://arxiv.org/abs/2610.36229" target="_blank" rel="noreferrer">Horikawa et al.</a>). <em>Week 1.</em></p><h3 id="autopilot-mode" tabindex="-1">Autopilot mode <a class="header-anchor" href="#autopilot-mode" aria-label="Permalink to &quot;Autopilot mode&quot;">​</a></h3><p>Any agent setting that runs commands or writes without asking (also called auto-approve, &quot;yolo&quot; or skip-permissions mode). Banned in this course (<a href="./../setup/safety-contract.html#2-approvals-stay-on">rule 2</a>). <em>Week 1.</em></p><h2 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h2><h3 id="background-agent" tabindex="-1">Background agent <a class="header-anchor" href="#background-agent" aria-label="Permalink to &quot;Background agent&quot;">​</a></h3><p>An agent that runs remotely on a task (often from a GitHub issue) and returns a branch or pull request, while you do something else. Also <em>cloud agent</em>. <em>Week 13.</em></p><h3 id="beat" tabindex="-1">Beat <a class="header-anchor" href="#beat" aria-label="Permalink to &quot;Beat&quot;">​</a></h3><p>A planned change to a specification partway through an assignment (&quot;v1 against a spec, then the spec changes under you&quot;), from UT Austin CS 378&#39;s homework design. Week 5&#39;s assignment has one. <em>Week 5.</em></p><h3 id="benchmark-contamination" tabindex="-1">Benchmark contamination <a class="header-anchor" href="#benchmark-contamination" aria-label="Permalink to &quot;Benchmark contamination&quot;">​</a></h3><p>When a benchmark&#39;s tasks or solutions were in a model&#39;s training data, so a score measures memory rather than skill. Date-windowed benchmarks compare tasks before and after a model&#39;s cutoff. See <a href="./case-studies.html#d4-remembering-instead-of-reasoning">case D4</a>. <em>Week 12.</em></p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><h3 id="canary" tabindex="-1">Canary <a class="header-anchor" href="#canary" aria-label="Permalink to &quot;Canary&quot;">​</a></h3><p>A fake, worthless secret (<code>CANARY-…</code>) planted to detect a leak: if it shows up somewhere it shouldn&#39;t, something exfiltrated it. The week 4 injection lab uses one. <em>Week 4.</em></p><h3 id="characterization-test" tabindex="-1">Characterization test <a class="header-anchor" href="#characterization-test" aria-label="Permalink to &quot;Characterization test&quot;">​</a></h3><p>A test that records what existing code <em>does</em> now, right or wrong, so a refactor can prove it changed nothing. <em>Week 8.</em></p><h3 id="check-first" tabindex="-1">Check first <a class="header-anchor" href="#check-first" aria-label="Permalink to &quot;Check first&quot;">​</a></h3><p>Writing the test or acceptance check before asking an agent for the code, in a separate prompt or session, so the check isn&#39;t bent to fit the code. Tests generated after faulty code caught 14% of its faults against 25% for tests generated independently (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>). <em>Week 5.</em></p><h3 id="checkoff" tabindex="-1">Checkoff <a class="header-anchor" href="#checkoff" aria-label="Permalink to &quot;Checkoff&quot;">​</a></h3><p>The last 15 minutes of each Lab, when staff check the week&#39;s in-lab deliverable. <em>Every week.</em></p><h3 id="class-codebase" tabindex="-1">Class codebase <a class="header-anchor" href="#class-codebase" aria-label="Permalink to &quot;Class codebase&quot;">​</a></h3><p>The real open-source project the instructor forks for the class each term; teams work in their own forks of that class fork. Current pick: <a href="./../TOOLS.html#the-class-codebase">Tool Handout: The class codebase</a>; details: <a href="./../project/class-codebase.html">The Class Codebase</a>. <em>Week 2.</em></p><h3 id="cohens-kappa-κ" tabindex="-1">Cohen&#39;s kappa (κ) <a class="header-anchor" href="#cohens-kappa-κ" aria-label="Permalink to &quot;Cohen&#39;s kappa (κ)&quot;">​</a></h3><p>Agreement between two raters corrected for chance: 1 is perfect, 0 is chance level. Report it alongside percent agreement for an <a href="#llm-as-judge">LLM judge</a>, because a judge that always says &quot;pass&quot; agrees 95% of the time with labels that are 95% passes, yet κ is 0 (<a href="https://arxiv.org/abs/2406.12624" target="_blank" rel="noreferrer">Thakur et al.</a>; <a href="https://hamel.dev/blog/posts/llm-judge/" target="_blank" rel="noreferrer">Husain</a>). <em>Week 12.</em></p><h3 id="compaction" tabindex="-1">Compaction <a class="header-anchor" href="#compaction" aria-label="Permalink to &quot;Compaction&quot;">​</a></h3><p>Replacing older parts of an agent&#39;s conversation with a summary when the context fills up, so the session can continue. It loses detail, which is one reason to keep tasks small. <em>Week 2.</em></p><h3 id="context-engineering" tabindex="-1">Context engineering <a class="header-anchor" href="#context-engineering" aria-label="Permalink to &quot;Context engineering&quot;">​</a></h3><p>Deciding what goes into a model&#39;s context, and what stays out: instructions, specifications, tools, retrieved files, history. More is not better (see <a href="#context-rot">context rot</a>). <em>Week 3.</em></p><h3 id="context-rot" tabindex="-1">Context rot <a class="header-anchor" href="#context-rot" aria-label="Permalink to &quot;Context rot&quot;">​</a></h3><p>Performance falling as input length grows. In all 18 models Chroma tested, performance degraded with longer inputs, faster with distractors; a focused prompt of about 300 tokens beat the full 113K-token one (<a href="https://www.trychroma.com/research/context-rot" target="_blank" rel="noreferrer">Hong et al.</a>). <em>Week 3.</em></p><h3 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context window&quot;">​</a></h3><p>The maximum number of tokens a model can read in one request: system prompt, tool schemas, conversation and files together. A local model&#39;s <em>configured</em> context can be much smaller than the model&#39;s maximum (<a href="./../setup/local-models.html#the-64k-context-setting-and-why-tool-calls-fail-silently-without-it">local models</a>). <em>Week 1.</em></p><h3 id="criteria-drift" tabindex="-1">Criteria drift <a class="header-anchor" href="#criteria-drift" aria-label="Permalink to &quot;Criteria drift&quot;">​</a></h3><p>The finding that grading a model&#39;s outputs changes your grading criteria, and that some criteria appear only after you see outputs (<a href="https://arxiv.org/abs/2404.12272" target="_blank" rel="noreferrer">Shankar et al.</a>). So don&#39;t freeze an eval rubric before looking at data. <em>Week 12.</em></p><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><h3 id="dependency-confusion" tabindex="-1">Dependency confusion <a class="header-anchor" href="#dependency-confusion" aria-label="Permalink to &quot;Dependency confusion&quot;">​</a></h3><p>An attack on how package names resolve: someone publishes a package on the public registry under a name your project uses only internally, usually with a higher version, and a misconfigured install picks the public one. Controls: scoped names mapped to your registry, a lockfile with resolved URLs and integrity hashes, and <code>npm ci</code> in CI. A relative of <a href="#slopsquatting">slopsquatting</a>. <em>Week 10.</em></p><h3 id="dev-container" tabindex="-1">Dev container <a class="header-anchor" href="#dev-container" aria-label="Permalink to &quot;Dev container&quot;">​</a></h3><p>A Docker container defined by <code>.devcontainer/devcontainer.json</code>, used by both Codespaces and VS Code locally. Its config runs commands when it&#39;s built, so read one before you use it (<a href="./../setup/sandboxes.html">sandboxes</a>). <em>Week 0.</em></p><h3 id="due-date-quiz" tabindex="-1">Due-date quiz <a class="header-anchor" href="#due-date-quiz" aria-label="Permalink to &quot;Due-date quiz&quot;">​</a></h3><p>A 7-minute, 🔴 AI-off quiz at the start of the Seminar on the day an assignment is due, about that assignment (UT Austin CS 378&#39;s practice). Weeks 2–14. <a href="./../assessment/quizzes.html">Due-Date Quizzes</a>. <em>Weeks 2–14.</em></p><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><h3 id="ears" tabindex="-1">EARS <a class="header-anchor" href="#ears" aria-label="Permalink to &quot;EARS&quot;">​</a></h3><p><em>Easy Approach to Requirements Syntax</em>: acceptance criteria in fixed patterns. The course&#39;s default is the event-driven form <strong>WHEN</strong> <em>trigger</em> <strong>THE SYSTEM SHALL</strong> <em>response</em>; others are WHILE (state), IF … THEN (unwanted behavior), WHERE (optional feature) and the plain ubiquitous SHALL. Template: <a href="./../templates/SPEC.html">SPEC.md template</a>. <em>Week 5.</em></p><h3 id="egress-block" tabindex="-1">Egress block <a class="header-anchor" href="#egress-block" aria-label="Permalink to &quot;Egress block&quot;">​</a></h3><p>A rule that lets a process reach only allowlisted hosts, removing an agent&#39;s way to send data out. Enforced by the network (a firewall, a sandbox), it is a control; enforced by a harness inspecting command strings, as in week 4&#39;s <code>injection-lab</code>, it is a speed bump that encodings and other tools can get past. <em>Week 4.</em></p><h3 id="equivalent-mutant" tabindex="-1">Equivalent mutant <a class="header-anchor" href="#equivalent-mutant" aria-label="Permalink to &quot;Equivalent mutant&quot;">​</a></h3><p>A <a href="#mutation-testing">mutant</a> that behaves identically to the original program, so no test can kill it. It lowers the mutation score without indicating a weak test; deciding equivalence takes judgment (or a detector: Meta&#39;s reached 0.95 precision, <a href="https://arxiv.org/abs/2501.12862" target="_blank" rel="noreferrer">Foster et al.</a>). <em>Week 7.</em></p><h3 id="eval" tabindex="-1">Eval <a class="header-anchor" href="#eval" aria-label="Permalink to &quot;Eval&quot;">​</a></h3><p>A repeatable measurement of an LLM feature or agent on a fixed set of cases, with a metric and, ideally, error bars. <strong>Capability evals</strong> ask what it can do; <strong>regression evals</strong> check that it still does what it did (<a href="https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents" target="_blank" rel="noreferrer">Anthropic</a>). <em>Weeks 11–12.</em></p><h3 id="excessive-agency" tabindex="-1">Excessive agency <a class="header-anchor" href="#excessive-agency" aria-label="Permalink to &quot;Excessive agency&quot;">​</a></h3><p>OWASP&#39;s name for giving an LLM system more tools, permissions or autonomy than its task needs. Third in the 2026 LLM Top 10, up from sixth (<a href="https://genai.owasp.org/resource/owasp-genai-llm-top-10-2026/" target="_blank" rel="noreferrer">OWASP</a>). <em>Week 4.</em></p><h3 id="exploit-test" tabindex="-1">Exploit test <a class="header-anchor" href="#exploit-test" aria-label="Permalink to &quot;Exploit test&quot;">​</a></h3><p>A test written from the attacker&#39;s side: the attacker&#39;s request, exactly as they would send it, then an assertion of the response the specification requires (<code>403</code>, <code>400</code>) <strong>and</strong> that nothing changed. Scanners find dangerous patterns in code; an exploit test checks behavior (who may do what, with which input), and once it passes it pins the control, so no later refactor removes it unnoticed. <em>Week 10.</em></p><h2 id="f" tabindex="-1">F <a class="header-anchor" href="#f" aria-label="Permalink to &quot;F&quot;">​</a></h2><h3 id="final-defense" tabindex="-1">Final defense <a class="header-anchor" href="#final-defense" aria-label="Permalink to &quot;Final defense&quot;">​</a></h3><p>The finals-week event: team demos and live individual questions, in the scheduled 2-hour final exam slot. <a href="./../project/final-defense.html">The Final Defense</a>. <em>Week 16.</em></p><h3 id="fine-grained-token" tabindex="-1">Fine-grained token <a class="header-anchor" href="#fine-grained-token" aria-label="Permalink to &quot;Fine-grained token&quot;">​</a></h3><p>A GitHub personal access token limited to selected repositories, specific permissions and an expiry date. The course&#39;s only kind of token for agents and CI (<a href="./../setup/api-keys.html#scoped-tokens">api-keys</a>). <em>Week 4.</em></p><h3 id="free-tier" tabindex="-1">Free tier <a class="header-anchor" href="#free-tier" aria-label="Permalink to &quot;Free tier&quot;">​</a></h3><p>A no-cost allowance on a metered service. In this course, every free tier has no payment method behind it, so its spending cap is zero. Current allowances: <a href="./../TOOLS.html#spreading-the-work-across-free-allowances">Tool Handout: Spreading the work across free allowances</a>. <em>Week 0.</em></p><h2 id="g" tabindex="-1">G <a class="header-anchor" href="#g" aria-label="Permalink to &quot;G&quot;">​</a></h2><h3 id="goldfish-test" tabindex="-1">Goldfish test <a class="header-anchor" href="#goldfish-test" aria-label="Permalink to &quot;Goldfish test&quot;">​</a></h3><p>Give a fresh agent session (one with no memory of your work) only a document, such as <code>SPEC.md</code>, <code>TASKS.md</code> or <code>AGENTS.md</code>, and see whether it can work from that alone. Wherever it guesses or asks, the document is leaning on context that lives in your head. From Michigan EECS 498&#39;s Elephant-Goldfish Model. <a href="./agent-patterns.html#the-goldfish-test">Agent Patterns: The Goldfish test</a>. <em>Weeks 3 and 5.</em></p><h3 id="grace-token" tabindex="-1">Grace token <a class="header-anchor" href="#grace-token" aria-label="Permalink to &quot;Grace token&quot;">​</a></h3><p>One of two 48-hour extensions each student may use on labs and assignments; not on quizzes, oral exams, the PR round or the final defense. <a href="./../assessment/">Assessment</a>. <em>Week 1.</em></p><h2 id="h" tabindex="-1">H <a class="header-anchor" href="#h" aria-label="Permalink to &quot;H&quot;">​</a></h2><h3 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h3><p>Everything around the model in an agent: the system prompt, tool definitions and their implementations, the loop, context management, permissions and sandboxing. A score belongs to model <em>plus</em> harness: scaffolds alone shift benchmark scores by tens of points (<a href="./../research/notes/evidence-senior.html">evidence notes</a>). <em>Week 2.</em></p><h3 id="human-in-the-loop" tabindex="-1">Human in the loop <a class="header-anchor" href="#human-in-the-loop" aria-label="Permalink to &quot;Human in the loop&quot;">​</a></h3><p>A design in which a person approves or reviews agent actions at defined points. Most open-source AI policies require it (<a href="https://arxiv.org/abs/2605.16706" target="_blank" rel="noreferrer">Hora &amp; Robbes</a>). <em>Weeks 1 and 13.</em></p><h2 id="i" tabindex="-1">I <a class="header-anchor" href="#i" aria-label="Permalink to &quot;I&quot;">​</a></h2><h3 id="indirect-prompt-injection" tabindex="-1">Indirect prompt injection <a class="header-anchor" href="#indirect-prompt-injection" aria-label="Permalink to &quot;Indirect prompt injection&quot;">​</a></h3><p><a href="#prompt-injection">Prompt injection</a> delivered through content the agent reads rather than through the user: a README, an issue, a web page, a tool result, a code comment. <em>Week 4.</em></p><h2 id="j" tabindex="-1">J <a class="header-anchor" href="#j" aria-label="Permalink to &quot;J&quot;">​</a></h2><h3 id="json-rpc" tabindex="-1">JSON-RPC <a class="header-anchor" href="#json-rpc" aria-label="Permalink to &quot;JSON-RPC&quot;">​</a></h3><p>A small protocol for remote procedure calls in JSON (<code>{&quot;jsonrpc&quot;: &quot;2.0&quot;, &quot;id&quot;: 1, &quot;method&quot;: &quot;tools/list&quot;}</code>). MCP is built on JSON-RPC 2.0; over stdio, each message is one line. <em>Week 3.</em></p><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><h3 id="lethal-trifecta" tabindex="-1">Lethal trifecta <a class="header-anchor" href="#lethal-trifecta" aria-label="Permalink to &quot;Lethal trifecta&quot;">​</a></h3><p>Simon Willison&#39;s name for an agent with access to <strong>private data</strong>, exposure to <strong>untrusted content</strong> and a <strong>way to send data out</strong>. With all three, prompt injection can make it leak the data. Remove a leg per session (<a href="./case-studies.html#a1-supabase-mcp-the-lethal-trifecta-in-one-server">case A1</a>). <em>Week 4.</em></p><h3 id="llm-as-judge" tabindex="-1">LLM-as-judge <a class="header-anchor" href="#llm-as-judge" aria-label="Permalink to &quot;LLM-as-judge&quot;">​</a></h3><p>Using a model to grade another model&#39;s outputs. A judge is a model of a human grader, so calibrate it against human labels and report <a href="#cohens-kappa-κ">κ</a>, true-positive and true-negative rates, not just agreement. <em>Week 12.</em></p><h3 id="local-model" tabindex="-1">Local model <a class="header-anchor" href="#local-model" aria-label="Permalink to &quot;Local model&quot;">​</a></h3><p>A model run on your own hardware or the lab machine, typically through Ollama. Private and unlimited, but weaker, and sensitive to its configured <a href="#context-window">context window</a> (<a href="./../setup/local-models.html">local models</a>). <em>Weeks 0–1.</em></p><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><h3 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h3><p><em>Model Context Protocol</em>: an open protocol, built on <a href="#json-rpc">JSON-RPC</a>, through which an agent (the <em>client</em>) discovers and calls tools offered by a <em>server</em>, over stdio or HTTP. Writing a server means implementing methods such as <code>tools/list</code> and <code>tools/call</code>. The spec&#39;s current version and SDKs are in <a href="./../TOOLS.html#free-infrastructure">Tool Handout: Free infrastructure</a>. <em>Week 3.</em></p><h3 id="mutation-score" tabindex="-1">Mutation score <a class="header-anchor" href="#mutation-score" aria-label="Permalink to &quot;Mutation score&quot;">​</a></h3><p>The share of <a href="#mutation-testing">mutants</a> a test suite kills (excluding equivalent ones). A better measure of test adequacy than coverage: suites with 100% coverage can have very low mutation scores (<a href="https://arxiv.org/html/2506.02954v5" target="_blank" rel="noreferrer">MutGen</a>), though both measures are unreliable when the code may already be buggy (<a href="https://arxiv.org/abs/2607.22880" target="_blank" rel="noreferrer">Zhao, Zhou &amp; Cohen</a>). <em>Week 7.</em></p><h3 id="mutation-testing" tabindex="-1">Mutation testing <a class="header-anchor" href="#mutation-testing" aria-label="Permalink to &quot;Mutation testing&quot;">​</a></h3><p>Making small deliberate changes (<em>mutants</em>) to code, such as <code>&lt;</code> to <code>&lt;=</code>, and running the tests: a test that fails <em>kills</em> the mutant; a surviving mutant shows a behavior no test checks. Tools: StrykerJS (JavaScript), mutmut (Python). <em>Week 7.</em></p><h2 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h2><h3 id="observed-and-inferred" tabindex="-1">Observed and inferred <a class="header-anchor" href="#observed-and-inferred" aria-label="Permalink to &quot;Observed and inferred&quot;">​</a></h3><p>The course&#39;s claim tags, from Stanford CS146S. <strong>Observed:</strong> you ran it or read it, and can show the output or the line. <strong>Inferred:</strong> you or an AI concluded it. Only observed claims count as verified. <em>Week 1.</em></p><h3 id="ollama" tabindex="-1">Ollama <a class="header-anchor" href="#ollama" aria-label="Permalink to &quot;Ollama&quot;">​</a></h3><p>An open-source server that runs local models and exposes an OpenAI-compatible API on port 11434. Configure its context length for agents (<a href="./../setup/local-models.html">local models</a>). <em>Week 0.</em></p><h3 id="openai-compatible-api" tabindex="-1">OpenAI-compatible API <a class="header-anchor" href="#openai-compatible-api" aria-label="Permalink to &quot;OpenAI-compatible API&quot;">​</a></h3><p>An HTTP API that accepts OpenAI&#39;s chat-completions request format (<code>/chat/completions</code>, <code>messages</code>, <code>tools</code>). Most providers and Ollama offer one, which is why the kits switch provider with three environment variables (<a href="./../setup/api-keys.html">api-keys</a>). <em>Week 1.</em></p><h3 id="oral-exam" tabindex="-1">Oral exam <a class="header-anchor" href="#oral-exam" aria-label="Permalink to &quot;Oral exam&quot;">​</a></h3><p>A 15-minute, individual, 🔴 AI-off exam in weeks 8 and 14, about your own work. <a href="./../assessment/oral-exams.html">Oral Exams</a>. <em>Weeks 8 and 14.</em></p><h3 id="oracle" tabindex="-1">Oracle <a class="header-anchor" href="#oracle" aria-label="Permalink to &quot;Oracle&quot;">​</a></h3><p>What decides whether a test&#39;s output is correct. LLM-generated oracles tend to capture what the code <em>does</em> rather than what it <em>should</em> do, which hides bugs (<a href="https://arxiv.org/abs/2410.21136" target="_blank" rel="noreferrer">Konstantinou, Degiovanni &amp; Papadakis</a>). <em>Week 6.</em></p><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><h3 id="passk-and-passk" tabindex="-1">pass@k and pass^k <a class="header-anchor" href="#passk-and-passk" aria-label="Permalink to &quot;pass@k and pass^k&quot;">​</a></h3><p><strong>pass@k:</strong> the probability that at least one of k attempts succeeds (a capability measure). <strong>pass^k:</strong> the probability that all k attempts succeed (a reliability measure). In τ-bench, pass^8 was below 25% in retail (<a href="https://arxiv.org/abs/2406.12045" target="_blank" rel="noreferrer">Yao et al.</a>). <em>Week 12.</em></p><h3 id="plan-mode" tabindex="-1">Plan mode <a class="header-anchor" href="#plan-mode" aria-label="Permalink to &quot;Plan mode&quot;">​</a></h3><p>A harness mode in which the agent may read and propose a plan but not edit or run anything until you approve. <a href="./agent-patterns.html#plan-first">Agent Patterns: Plan first</a>. <em>Week 5.</em></p><h3 id="pr-round" tabindex="-1">PR round <a class="header-anchor" href="#pr-round" aria-label="Permalink to &quot;PR round&quot;">​</a></h3><p>Weeks 9–10: each student opens one pull request on another team&#39;s fork, and the receiving team reviews it and decides. From UT Austin CS 378. <a href="./../project/pr-round.html">The PR Round</a>. <em>Weeks 9–10.</em></p><h3 id="precision-and-recall" tabindex="-1">Precision and recall <a class="header-anchor" href="#precision-and-recall" aria-label="Permalink to &quot;Precision and recall&quot;">​</a></h3><p>For a reviewer (human or AI) scored against a defect key: <strong>precision</strong> is the share of its comments that point at real defects; <strong>recall</strong> is the share of real defects it found. <em>Week 9.</em></p><h3 id="prompt-injection" tabindex="-1">Prompt injection <a class="header-anchor" href="#prompt-injection" aria-label="Permalink to &quot;Prompt injection&quot;">​</a></h3><p>Text that makes a model follow instructions its user didn&#39;t give. <em>Direct</em> comes from the user&#39;s input; <a href="#indirect-prompt-injection">indirect</a> arrives in content the model reads. First in OWASP&#39;s 2026 LLM Top 10. <em>Week 4.</em></p><h3 id="property-based-testing" tabindex="-1">Property-based testing <a class="header-anchor" href="#property-based-testing" aria-label="Permalink to &quot;Property-based testing&quot;">​</a></h3><p>Testing a function against a stated property (&quot;no two bookings overlap&quot;) on many generated inputs, with automatic shrinking of failures to a minimal case. Tools: fast-check (JavaScript), Hypothesis (Python). <em>Week 6.</em></p><h2 id="q" tabindex="-1">Q <a class="header-anchor" href="#q" aria-label="Permalink to &quot;Q&quot;">​</a></h2><h3 id="quarantined-reading" tabindex="-1">Quarantined reading <a class="header-anchor" href="#quarantined-reading" aria-label="Permalink to &quot;Quarantined reading&quot;">​</a></h3><p>A defense in which untrusted text is processed by a model call that has <strong>no tools</strong>, and only a constrained result (a summary, a field) reaches the agent that can act. Also the <em>dual LLM</em> pattern (<a href="https://arxiv.org/abs/2506.08837" target="_blank" rel="noreferrer">Beurer-Kellner et al.</a>; <a href="https://arxiv.org/abs/2503.18813" target="_blank" rel="noreferrer">CaMeL</a>). <em>Week 4.</em></p><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><h3 id="ratchet" tabindex="-1">Ratchet <a class="header-anchor" href="#ratchet" aria-label="Permalink to &quot;Ratchet&quot;">​</a></h3><p>A CI gate on old code that blocks only what a pull request makes worse: lint only the files it changes, or report only the findings introduced since its base commit. Existing warnings don&#39;t block anyone, and no PR adds new ones; a gate that is red on <code>main</code> forever teaches everyone to ignore red. <em>Week 9.</em></p><h3 id="rate-limit" tabindex="-1">Rate limit <a class="header-anchor" href="#rate-limit" aria-label="Permalink to &quot;Rate limit&quot;">​</a></h3><p>A provider&#39;s cap on requests or tokens per minute or day. Exceeding it returns HTTP 429; well-behaved clients retry with exponential backoff. Free-tier limits: <a href="./../TOOLS.html#spreading-the-work-across-free-allowances">Tool Handout: Spreading the work across free allowances</a>. <em>Week 1.</em></p><h3 id="recorded-responses" tabindex="-1">Recorded responses <a class="header-anchor" href="#recorded-responses" aria-label="Permalink to &quot;Recorded responses&quot;">​</a></h3><p>Saved model outputs that let tests and CI run an eval offline and deterministically, with no key and no cost. The <code>eval-harness</code> kit&#39;s tests use them. <em>Week 12.</em></p><h3 id="retrieval-augmented-generation-rag" tabindex="-1">Retrieval-augmented generation (RAG) <a class="header-anchor" href="#retrieval-augmented-generation-rag" aria-label="Permalink to &quot;Retrieval-augmented generation (RAG)&quot;">​</a></h3><p>Fetching relevant documents and putting them in the prompt. It has known failure points (missing content, missed top-ranked documents, wrong specificity…) and &quot;can only be fully validated in operation&quot; (<a href="https://arxiv.org/abs/2401.05856" target="_blank" rel="noreferrer">Barnett et al.</a>). <em>Week 11.</em></p><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><h3 id="safe-loop" tabindex="-1">Safe Loop <a class="header-anchor" href="#safe-loop" aria-label="Permalink to &quot;Safe Loop&quot;">​</a></h3><p>The inner loop inherited from the sibling course: Describe → Plan → Step → Test → Read → Commit. <a href="./safe-loop.html">Specify · Delegate · Verify, and the Safe Loop</a>. <em>Week 1.</em></p><h3 id="sandbox" tabindex="-1">Sandbox <a class="header-anchor" href="#sandbox" aria-label="Permalink to &quot;Sandbox&quot;">​</a></h3><p>An environment that limits what an agent can reach: a Codespace, a dev container, a microVM. It moves the blast radius rather than removing it; filesystem and network isolation are both needed (<a href="./../setup/sandboxes.html#what-a-sandbox-does-and-doesnt-protect">sandboxes</a>). <em>Weeks 0, 2 and 4.</em></p><h3 id="sbom" tabindex="-1">SBOM <a class="header-anchor" href="#sbom" aria-label="Permalink to &quot;SBOM&quot;">​</a></h3><p><em>Software bill of materials</em>: a machine-readable list of every component you ship, by name and version (week 10 generates one with <code>npm sbom</code>). When the next advisory lands, it answers &quot;are we affected?&quot; in a minute; it doesn&#39;t show that any component is safe. <em>Week 10.</em></p><h3 id="seam" tabindex="-1">Seam <a class="header-anchor" href="#seam" aria-label="Permalink to &quot;Seam&quot;">​</a></h3><p>A place where you can change a program&#39;s behavior without editing the code there (an injected dependency, a module boundary), used to get legacy code under test. <em>Week 8.</em></p><h3 id="seeded-bug" tabindex="-1">Seeded bug <a class="header-anchor" href="#seeded-bug" aria-label="Permalink to &quot;Seeded bug&quot;">​</a></h3><p>A bug planted on purpose in a kit for students to find; <code>roomly</code> has several, listed only in the instructor&#39;s answer key. <em>Weeks 6–7.</em></p><h3 id="skill" tabindex="-1">Skill <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;Skill&quot;">​</a></h3><p>A folder of instructions (a <code>SKILL.md</code>, sometimes scripts) that an agent loads when a task matches its description. A skill can make the agent do anything it is allowed to do: read one before you adopt it (<a href="./../setup/safety-contract.html#8-read-before-you-adopt">rule 8</a>). <em>Week 3.</em></p><h3 id="slopsquatting" tabindex="-1">Slopsquatting <a class="header-anchor" href="#slopsquatting" aria-label="Permalink to &quot;Slopsquatting&quot;">​</a></h3><p>Registering package names that models tend to invent, so an agent that installs an invented dependency installs malware (<a href="./case-studies.html#b5-slopsquatting-packages-that-dont-exist">case B5</a>). <em>Week 10.</em></p><h3 id="specify--delegate--verify" tabindex="-1">Specify · Delegate · Verify <a class="header-anchor" href="#specify--delegate--verify" aria-label="Permalink to &quot;Specify · Delegate · Verify&quot;">​</a></h3><p>The course&#39;s core triad, from UT Austin CS 378: before you start, decide what you will specify, what you will delegate to an agent, and how you will verify it. <a href="./safe-loop.html#specify--delegate--verify">Specify · Delegate · Verify, and the Safe Loop: Specify · Delegate · Verify</a>. <em>Week 1.</em></p><h3 id="strangler-fig" tabindex="-1">Strangler fig <a class="header-anchor" href="#strangler-fig" aria-label="Permalink to &quot;Strangler fig&quot;">​</a></h3><p>A way to migrate code by growing the new implementation around the old: route one call at a time to the new code, run both and compare their results (a <em>parallel run</em>) while the old path stays authoritative, and delete the old path last. Martin Fowler&#39;s name, after a vine that grows around a tree. <em>Week 8.</em></p><h3 id="structured-output" tabindex="-1">Structured output <a class="header-anchor" href="#structured-output" aria-label="Permalink to &quot;Structured output&quot;">​</a></h3><p>Constraining a model to return output matching a schema (JSON Schema, a grammar), by API feature or constrained decoding. Validate it anyway, and retry on failure. <em>Week 11.</em></p><h3 id="subagent" tabindex="-1">Subagent <a class="header-anchor" href="#subagent" aria-label="Permalink to &quot;Subagent&quot;">​</a></h3><p>A separate agent session started by a parent agent for a sub-task, with its own fresh context, returning only a summary. Useful for keeping the parent&#39;s context small. <a href="./agent-patterns.html#subagents">Agent Patterns: Subagents</a>. <em>Week 2.</em></p><h3 id="swe-bench" tabindex="-1">SWE-bench <a class="header-anchor" href="#swe-bench" aria-label="Permalink to &quot;SWE-bench&quot;">​</a></h3><p>A family of benchmarks in which an agent must resolve real GitHub issues so that held-out tests pass. Every major variant has been shown to overstate capability (<a href="./case-studies.html#benchmark-inflation">benchmark inflation</a>). <em>Weeks 1 and 12.</em></p><h3 id="system-prompt" tabindex="-1">System prompt <a class="header-anchor" href="#system-prompt" aria-label="Permalink to &quot;System prompt&quot;">​</a></h3><p>The instructions a harness sends before the conversation: role, rules, and usually the tool schemas. In week 1&#39;s trace dissection you read a real one. <em>Week 1.</em></p><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><h3 id="time-horizon" tabindex="-1">Time horizon <a class="header-anchor" href="#time-horizon" aria-label="Permalink to &quot;Time horizon&quot;">​</a></h3><p>METR&#39;s measure of agent capability: the length of task (in human expert time) an agent completes with 50% reliability. It has been doubling roughly every 7 months since 2019 (<a href="https://arxiv.org/abs/2503.14499" target="_blank" rel="noreferrer">Kwa et al.</a>). <em>Weeks 1 and 15.</em></p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>The unit a model reads and writes, roughly three-quarters of an English word. Context windows, rate limits and prices are counted in tokens. <em>Week 1.</em></p><h3 id="tool-call" tabindex="-1">Tool call <a class="header-anchor" href="#tool-call" aria-label="Permalink to &quot;Tool call&quot;">​</a></h3><p>A model&#39;s structured request to run a named tool with JSON arguments (for example <code>list_files</code> with <code>{&quot;path&quot;: &quot;src&quot;}</code>), which the harness executes and returns. The model never runs anything itself. <em>Week 1.</em></p><h3 id="tool-poisoning" tabindex="-1">Tool poisoning <a class="header-anchor" href="#tool-poisoning" aria-label="Permalink to &quot;Tool poisoning&quot;">​</a></h3><p>Hiding instructions in an MCP tool&#39;s description or metadata, which the model sees and the user usually doesn&#39;t (<a href="./case-studies.html#a3-mcp-tool-poisoning-instructions-the-user-never-sees">case A3</a>). <em>Week 4.</em></p><h3 id="trace" tabindex="-1">Trace <a class="header-anchor" href="#trace" aria-label="Permalink to &quot;Trace&quot;">​</a></h3><p>A record of every request and response in an agent session. <code>mini-agent</code> writes one as JSONL; week 1&#39;s trace dissection reads one from a real agent. <em>Week 1.</em></p><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h2><h3 id="vibe-coding" tabindex="-1">Vibe coding <a class="header-anchor" href="#vibe-coding" aria-label="Permalink to &quot;Vibe coding&quot;">​</a></h3><p>Accepting AI-written code without reading it, in Andrej Karpathy&#39;s original sense; fine for a throwaway, not for software anyone relies on. Where this course starts its story, not its practice. <em>Week 1.</em></p><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><h3 id="worktree" tabindex="-1">Worktree <a class="header-anchor" href="#worktree" aria-label="Permalink to &quot;Worktree&quot;">​</a></h3><p>A second (or third) working directory attached to the same git repository, each on its own branch: <code>git worktree add ../roomly-issue-3 -b issue-3</code>. It lets several agents work in parallel without touching each other&#39;s files. <a href="./agent-patterns.html#worktrees">Agent Patterns: Worktrees</a>. <em>Week 13.</em></p>',194)])])}const p=a(n,[["render",s]]);export{u as __pageData,p as default};
